package com.bank.requests;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class QueueFromStacksDemo {

    private static final Logger log = Logger.getLogger(QueueFromStacksDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        RequestQueue queue = new RequestQueue();

        queue.enqueue("REQ-1");
        queue.enqueue("REQ-2");
        queue.enqueue("REQ-3");

        log.info(() -> "Serve: " + queue.dequeue());  // REQ-1 (oldest)

        queue.enqueue("REQ-4");

        log.info(() -> "Serve: " + queue.dequeue());  // REQ-2
        log.info(() -> "Serve: " + queue.dequeue());  // REQ-3
        log.info(() -> "Serve: " + queue.dequeue());  // REQ-4
    }
}

