class RequestQueue {

    private static final Logger log = Logger.getLogger(RequestQueue.class.getName());

    private final java.util.Deque<String> inbox = new java.util.ArrayDeque<>();
    private final java.util.Deque<String> outbox = new java.util.ArrayDeque<>();

    void enqueue(String id) {
        inbox.push(id);                       // newest on inbox top
        log.fine(() -> "  enqueue " + id);
    }

    String dequeue() {
        if (outbox.isEmpty()) {
            // Lazy transfer: reverse inbox into outbox so oldest is on top.
            while (!inbox.isEmpty()) {
                outbox.push(inbox.pop());
            }
            log.fine(() -> "  transferred inbox → outbox");
        }
        if (outbox.isEmpty()) {
            throw new java.util.NoSuchElementException("queue empty");
        }
        return outbox.pop();                  // oldest element
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
